-- perf_guard.lua: runtime half of PERFORMANCE.md for generated or ported addon code (generated by ForeverDump tools).
-- Rule: no measurable framerate impact (<1%), no idle OnUpdate, O(1) per-event cost, dirty-only throttled redraws,
-- heavy work out of combat or offline. Every perf run must finish within 2 minutes of wall time (hard cap).
--
--   local PG = dofile("mocks/perf_guard.lua")
--   local res = PG.flat({ grow = function(n) ... end,       -- bring the state to "n casts/events into the session"
--                         event = function() ... end,       -- one event through the handler under test
--                         marks = { 25, 50, 100 }, per = 200, ratio = 2, cap = 120 })
--   assert(res.ok, res.msg)
--   assert(PG.idleOnUpdates(frames) == 0)
local G = { CAP = 120, RATIO = 2, FPS = 60 }

local clock = os.clock
local wall = os.time

-- per-event cost at each growth checkpoint; fails when the cost at the last checkpoint is > ratio x the first
-- (plus a small absolute slack) or when the run would exceed the wall cap (aborts and reports the trend so far)
function G.flat(o)
    local marks, per, ratio = o.marks or { 25, 50, 100 }, o.per or 200, o.ratio or G.RATIO
    local cap = math.min(o.cap or G.CAP, G.CAP)
    local start = wall()
    local pts, aborted = {}, false
    for _, m in ipairs(marks) do
        if o.grow then o.grow(m) end
        local t0 = clock()
        for _ = 1, per do o.event() end
        local ms = (clock() - t0) * 1000 / per
        pts[#pts + 1] = { n = m, ms = ms }
        if wall() - start > cap then aborted = true break end
    end
    local first, last = pts[1], pts[#pts]
    local grew = last and first and last.ms > first.ms * ratio + (o.slack or 0.005)
    local trend = {}
    for _, p in ipairs(pts) do trend[#trend + 1] = string.format("n=%d %.4f ms/event", p.n, p.ms) end
    local msg = table.concat(trend, ", ")
    if aborted then msg = "ABORTED at the " .. cap .. " s cap; trend so far: " .. msg end
    local budget = o.eventsPerSecond and last and (last.ms * o.eventsPerSecond / 10) or nil   -- % of one second
    if budget and budget >= 1 then return { ok = false, points = pts, msg = "impact " .. budget .. "% >= 1%: " .. msg } end
    return { ok = not grew and not aborted, points = pts, aborted = aborted, msg = (grew and "per-event cost grows: " or "") .. msg }
end

-- frames that still run an OnUpdate while shown (call after the addon has gone idle)
function G.idleOnUpdates(frames)
    local n, names = 0, {}
    for _, f in ipairs(frames or {}) do
        local shown = not f.IsShown or f:IsShown()
        if shown and f.GetScript and f:GetScript("OnUpdate") then
            n = n + 1
            names[#names + 1] = (f.GetName and f:GetName()) or tostring(f)
        end
    end
    return n, names
end

return G
